use kobo_web_document::{Limits,SupplyBudget,SnapshotState,HistoryState,InputState,FocusState,TargetState};
fn snap()->SnapshotState{SnapshotState{history:None,input:None,focus:None,target:None}}
fn run(c:&str,b:&str,l:&Limits,s:&SnapshotState)->kobo_web_document::style_tree::StyleTree{let h=format!("<!doctype html><style>{c}</style>{b}");kobo_web_document::parse_style_tree_with_state(h.as_bytes(),&[],l,None,SupplyBudget::CANONICAL,s)}
#[test] fn browser_rank_ordinary_colors_and_expected_table_policy(){let h=include_str!("fixtures/has_class_pair_cascade.html");let ordinary=h.split(".client-js .mw-collapsible").next().unwrap().to_string()+"</style><div data-k=e class=z><b class=a></b></div><div data-k=w class=z><b class=b></b></div><div id=strong data-k=s class=z><b class=a></b></div><div data-k=m class='z q'><b class=b></b></div>";let t=run("",&ordinary,&Limits::DEFAULT,&snap());assert!(!t.unsupported&&!t.truncated);assert_eq!(t.nodes.iter().filter(|n|n.tag=="div").map(|n|n.style.color).collect::<Vec<_>>(),[0x0000ff,0x0000ff,0xff0000,0x0000ff]);for h in [include_str!("fixtures/has_class_pair_cascade.html"),include_str!("fixtures/has_class_pair_content_none.html")]{let t=run("",h,&Limits::DEFAULT,&snap());assert!(t.unsupported);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::CssDeclaration)>0);assert!(t.nodes.iter().all(|n|n.tag!="::before"));assert!(t.nodes.iter().filter(|n|n.tag=="table"||n.tag=="th").all(|n|n.style.color==0));}}
#[test] fn originals_parsed_origin_checked_but_table_th_positives_refused(){for(qi,q)in include_str!("fixtures/has_class_pair_original2.txt").lines().enumerate(){for(c,w)in[("",false),("mw-collapsible-toggle",true),("mw-collapsible-toggle-placeholder",true),("mw-collapsible-toggle mw-collapsible-toggle-placeholder",true),("MW-COLLAPSIBLE-TOGGLE",false),("mw-collapsible-toggleX",false),("mw-collapsible-toggle&#160;mw-collapsible-toggle-placeholder",false),("x&#9;mw-collapsible-toggle",true)]{let b=format!("<div class=client-js><table class=mw-collapsible><tbody><tr><th>head</th><td><b class='{c}'>x</b></td></tr></tbody></table></div>");for decl in ["color:red;content:\"\"","content:none!important"]{let t=run(&format!("{q}{{{decl}}}"),&b,&Limits::DEFAULT,&snap());let baseline=run("",&b,&Limits::DEFAULT,&snap());let reason=kobo_web_document::style_diagnostics::RefusalReason::CssDeclaration;assert!(baseline.unsupported&&t.unsupported,"table-UA baseline itself refused");assert_eq!(t.diagnostics.count(reason),baseline.diagnostics.count(reason)+usize::from(w),"additionalpseudoallowlistrefusal {q} {c}");assert!(t.nodes.iter().all(|n|n.tag!="::before"));assert!(t.nodes.iter().filter(|n|n.tag=="table"||n.tag=="th").all(|n|n.style.color==0));}}println!("HAS-PAIR-ORIGINAL {} parsed_origin_checked TABLE_TH_POSITIVES_REFUSED originalpositivegate_UNMET",qi+1);}}
#[test] fn global_work_attrloss_and_partial_state(){let q="div:has(.x,.y){color:red}";let b=format!("<div>{}</div>","<b class=z></b>".repeat(50));assert!(!run(q,&b,&Limits::DEFAULT,&snap()).truncated);let t=run(&q.repeat(100),&b.repeat(200),&Limits{max_input_bytes:4_000_000,max_nodes:200_000,..Limits::DEFAULT},&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);let b=format!("<div><b {} class=x></b></div>",(0..40).map(|i|format!("data-x{i}=a ")).collect::<String>());let t=run(q,&b,&Limits::DEFAULT,&snap());assert!(t.truncated&&t.diagnostics.dropped_attributes>0);assert!(!t.unsupported);for l in [Limits{max_input_bytes:30,..Limits::DEFAULT},Limits{max_nodes:1,..Limits::DEFAULT},Limits{max_text_bytes:0,..Limits::DEFAULT}]{let t=run(q,"<div><b>text</b></div>",&l,&snap());assert!(t.truncated||t.unsupported);}let q=".absent:has(.a,.b):where(:not(:focus)){color:red}";let mut s=snap();assert!(run(q,"<div></div>",&Limits::DEFAULT,&s).unsupported);s.history=Some(HistoryState::FreshNoHistory);s.input=Some(InputState::QuiescentCapture);assert!(run(q,"<div></div>",&Limits::DEFAULT,&s).unsupported);s.focus=Some(FocusState::UnfocusedInitial);assert!(!run(q,"<div></div>",&Limits::DEFAULT,&s).unsupported);assert!(run(q,"<div autofocus></div>",&Limits::DEFAULT,&s).unsupported);s.target=Some(TargetState::Fragment("x".into()));assert!(!run("div:has(.a,.b):target{color:red}","<div id=x><b class=a></b></div>",&Limits::DEFAULT,&s).unsupported);}
#[test] fn sixteen_seventeen_mixed_provenance_default_and_othercomma(){for(n,w)in[(16,false),(17,true)]{let q=vec![":has(.a,.b):not(.x,.y)";n].join(",");let t=run(&format!("{q}{{color:red}}"),"<div><b class=a></b></div>",&Limits::DEFAULT,&snap());assert_eq!(t.unsupported,w);}for q in [r#":has(.a,.b)[data-x="a,b"]"#,":has(.a,.b,.c)",":has(>.a,.b)"]{assert!(run(&format!("{q}{{color:red}}"),"<div><b class=a></b></div>",&Limits::DEFAULT,&snap()).unsupported);}let h=b"<!doctype html><style>div:has(.a,.b){color:red}</style><div><b class=a></b></div>";assert!(kobo_web_document::parse_style_tree(h,&[],&Limits::DEFAULT).unsupported);}
#[test] fn separate_allowed_div_pseudo_controls_not_original_table_support(){for(c,w)in[("",false),("a",true),("b",true),("a b",true)]{let b=format!("<div><b class='{c}'></b></div>");let t=run("div:has(.a,.b)::before{color:red;content:\"\"}",&b,&Limits::DEFAULT,&snap());assert!(!t.unsupported&&!t.truncated);let ps=t.nodes.iter().filter(|n|n.tag=="::before").collect::<Vec<_>>();assert_eq!(ps.len(),usize::from(w));if w{assert_eq!(ps[0].style.color,0xff0000);}assert!(t.nodes.iter().filter(|n|n.tag=="div").all(|n|n.style.color==0));}}

#[test] fn exact_second_original_on_allowed_div_is_synthetic_dom_only(){let q=include_str!("fixtures/has_class_pair_original2.txt").lines().nth(1).unwrap();let t=run(&format!("{q}{{color:red;content:\"\"}}"),"<div class=client-js><div class=mw-collapsible><b class=mw-collapsible-toggle></b></div></div>",&Limits::DEFAULT,&snap());assert!(!t.unsupported&&!t.truncated);assert_eq!(t.nodes.iter().filter(|n|n.tag=="::before").count(),1);}
#[test] fn ordinary_public_four_combinations_self_and_nondescendant(){for(c,w)in[("",0),("a",0xff0000),("b",0xff0000),("a b",0xff0000),("aa",0),("A",0),("a&#160;b",0),("x&#9;b",0xff0000)]{let b=format!("<div><b class='{c}'></b></div>");let t=run("div:has(.a,.b){color:red}",&b,&Limits::DEFAULT,&snap());assert!(!t.unsupported&&!t.truncated);assert_eq!(t.nodes.iter().find(|n|n.tag=="div").unwrap().style.color,w);}let t=run("div:has(.a,.b){color:red}","<div class=a></div><b class=b></b>",&Limits::DEFAULT,&snap());assert!(!t.unsupported&&!t.truncated);assert_eq!(t.nodes.iter().find(|n|n.tag=="div").unwrap().style.color,0);}
